// Build keyword lookup map
const buildKeywordMap = () => {
  const map = new Map();
  for (const [key, data] of Object.entries(SHELF_LIFE_DATABASE)) {
    for (const keyword of data.keywords) {
      const normalized = keyword.toLowerCase().trim();
      if (!map.has(normalized)) map.set(normalized, []);
      map.get(normalized).push({ key, ...data });
    }
  }
  return map;
};

const KEYWORD_MAP = buildKeywordMap();

/**
 * Look up shelf life for an item by name
 */
export function lookupShelfLife(itemName) {
  if (!itemName || typeof itemName !== 'string') {
    return { found: false, confidence: 'low' };
  }
  const normalized = itemName.toLowerCase().trim();
  
  // Exact match
  if (KEYWORD_MAP.has(normalized)) {
    const matches = KEYWORD_MAP.get(normalized);
    return { found: true, data: matches[0], confidence: 'high', matchedKey: matches[0].key };
  }
  
  // Partial match (longest first)
  const allKeywords = Array.from(KEYWORD_MAP.keys()).sort((a, b) => b.length - a.length);
  for (const keyword of allKeywords) {
    if (normalized.includes(keyword)) {
      const matches = KEYWORD_MAP.get(keyword);
      return { found: true, data: matches[0], confidence: 'medium', matchedKey: matches[0].key };
    }
  }
  
  return { found: false, confidence: 'low' };
}

export const CATEGORIES = ["Dairy","Meat","Vegetables","Fruits","Bakery","Beverages","Pantry","Frozen","Other"];

export const DEFAULT_SHELF_LIFE = {
  Dairy: 7,
  Meat: 3,
  Vegetables: 7,
  Fruits: 5,
  Bakery: 5,
  Beverages: 7,
  Pantry: 365,
  Frozen: 90,
  Other: 7,
};

/**
 * Infer category from item name when not found in database
 */
export function inferCategory(itemName) {
  const name = itemName.toLowerCase();

  const categoryIndicators = {
    Dairy: ['milk', 'cheese', 'yogurt', 'cream', 'butter', 'egg'],
    Meat: ['chicken', 'beef', 'pork', 'fish', 'salmon', 'shrimp', 'turkey', 'bacon', 'sausage', 'ham', 'meat', 'lamb', 'veal', 'duck', 'goose'],
    Vegetables: ['lettuce', 'spinach', 'broccoli', 'carrot', 'pepper', 'onion', 'tomato', 'potato', 'celery', 'mushroom', 'vegetable', 'cabbage', 'kale', 'squash'],
    Fruits: ['apple', 'banana', 'orange', 'berry', 'grape', 'melon', 'peach', 'pear', 'fruit', 'mango', 'pineapple', 'kiwi', 'lemon', 'lime'],
    Bakery: ['bread', 'bagel', 'muffin', 'roll', 'bun', 'cake', 'pie', 'pastry', 'croissant', 'donut', 'cookie'],
    Beverages: ['juice', 'drink', 'smoothie', 'tea', 'coffee', 'soda', 'water'],
    Frozen: ['frozen', 'ice cream'],
    Pantry: ['rice', 'pasta', 'cereal', 'flour', 'sugar', 'oil', 'vinegar', 'sauce', 'spice'],
  };

  for (const [category, indicators] of Object.entries(categoryIndicators)) {
    if (indicators.some(indicator => name.includes(indicator))) {
      return category;
    }
  }

  return 'Other';
}
